-- Language: en_US
insert or replace into EnglishText (Tag, Text) values
	("LOC_GAMEMODE_MONOPOLIES_NAME",                                  "Industries and Corporations Mode"),
	("LOC_GAMEMODE_MONOPOLIES_DESCRIPTION",                           "[COLOR_Civ6LightBlue]Welcome to ""Harmony in Diversity"": Industries and Corporations Mode, We have overhaul and redesigned the benefits of Industries, Corporations and Products. Please read the in-game civilopeida about the details.[ENDCOLOR][NEWLINE]Control, improve, and expand upon your Luxury resources! The Industries and Corporations mode enables you to build profitable Industries around Luxury resources, found Corporations to further their development, and manufacture unique Products to secure your place in business history."),
	("LOC_TRAIT_CIVILIZATION_AMAZON_DESCRIPTION_MONOPOLIES",          "Grant a Bandeirante after establishing [ICON_CAPITAL] Capital city. All districts (except city centers) will not remove Rainforest. Rainforest tiles provide a standard adjacency bonus for specialty districts, and grant +1 Appeal to adjacent tiles. When establishing an industry for the first time of each resource, grant a Bandeirante and all Bandeirantes receive +1 collection times. When you build Industry or Corporation on Rainforest tiles, immediately activate the corresponding bonus of all its usages."),
	("LOC_UNIT_HD_BANDEIRANTES_DESCRIPTION_MONOPOLIES",               "Brazilian unique Recon unit, but cannot be trained, purchased or upgraded to a more advanced unit. Its [ICON_STRENGTH] Combat Strength increases according to your era. It automatically creates roads when passing through Woods, Rainforest, Marsh{LOC_OR_SWAMP_NAME}. It can collect resources on unowned rainforest tiles for 4 times. For every two of the same resource collected, the improved Resources on rainforest tiles in your cities gain the yields of that resource."),
	("LOC_IMPROVEMENT_CHATEAU_DESCRIPTION_MONOPOLIES",			      		"+2 [ICON_FOOD] Food, +1 [ICON_Culture] Culture and +1 [ICON_HOUSING] Housing. +1 [ICON_FOOD] Food and [ICON_PRODUCTION] Production from every adjacent district. +2 [ICON_CULTURE] Culture from every adjacent Wonder. +1 [ICON_CULTURE] Culture from every Château in your empire. +1 Appeal to adjacent tiles. [NEWLINE]Upon construction, you may choose an improved Resource in this city of Crops, Fruit, Brewing or Beverage Usage as the ""[COLOR:Green]Production Resource[ENDCOLOR]"" for this Château. When the city has built a Medieval or later Wonder, you may choose an improved Resource in this city of Cloth, Art, Decoration or Ornamental Usage as the ""[COLOR:219,112,147,255]Entertainment Resource[ENDCOLOR]"" for this Château. The city receives the industrial bonuses of the selected resource; if a luxury resource is chosen, an additional copy of that resource is provided. [NEWLINE]Can only be built one per city.");

